// How the dev scripts set up paper (P3). Pure functions, tested by paper-env.test.mjs.
// - `pnpm dev` (dev.mjs) uses the real paper source unless the shell asks for a fake (R39).
// - `node scripts/camera.mjs` launches Electron through LaunchServices, so macOS treats it as
//   its own responsible process and its camera grant applies (Task 1's checks H and E).

/**
 * What dev.mjs adds to the app's env for paper. Plain `pnpm dev` adds nothing: `auto` is the
 * Desk View helper on the real camera on macOS (R39). `TASSEL_PAPER_SOURCE=fake-clip` plays the
 * demo clip (generated by `demoClip()` when the shell names none), and refuses real capture
 * unless the shell says otherwise. `real` says whether this run can open a real camera or screen.
 */
export function devPaperEnv(env, demoClip) {
  const source = env.TASSEL_PAPER_SOURCE || 'auto';
  if (source === 'fake-clip') {
    const add = {};
    if (!env.TASSEL_FAKE_CLIP) add.TASSEL_FAKE_CLIP = demoClip();
    if (env.TASSEL_REQUIRE_FAKE_CAPTURE === undefined) add.TASSEL_REQUIRE_FAKE_CAPTURE = '1';
    return { add, real: false };
  }
  const helperClip = source === 'deskview-helper' && Boolean(env.TASSEL_HELPER_CLIP);
  const selfDisplay =
    (source === 'window-capture' || source === 'screen') && env.TASSEL_FAKE_DISPLAY === 'self';
  return { add: {}, real: !helperClip && !selfDisplay };
}

/**
 * The `--env` pairs for a camera run: only desktop settings, with the real paper source
 * (`auto`), the given server and the plaintext token store as defaults. Never
 * TASSEL_REQUIRE_FAKE_CAPTURE, which would refuse the camera this run is for.
 */
export function cameraEnv(env, { serverUrl }) {
  const pass = {
    TASSEL_PAPER_SOURCE: 'auto',
    TASSEL_SERVER_URL: serverUrl,
    TASSEL_TOKEN_STORE: 'file',
  };
  for (const [name, value] of Object.entries(env)) {
    if (!DESKTOP_SETTINGS.has(name) || value === undefined) continue;
    pass[name] = value;
  }
  return Object.entries(pass).map(([name, value]) => `${name}=${value}`);
}

/**
 * `open`'s arguments for a LaunchServices launch: a new instance (-n) that open waits for (-W),
 * with the env pairs, its output in `log`, and `args` for Electron.
 */
export function openArgs({ electronApp, env, log, args }) {
  return [
    '-n',
    '-W',
    '-a',
    electronApp,
    ...env.flatMap((pair) => ['--env', pair]),
    ...(log ? ['--stdout', log, '--stderr', log] : []),
    '--args',
    ...args,
  ];
}

// Explicitly enumerate the settings consumed by main/config and main/paper/config. Server
// database, S3 and provider credentials must never reach Electron or open's command line.
const DESKTOP_SETTINGS = new Set([
  'TASSEL_SERVER_URL',
  'TASSEL_TOKEN_STORE',
  'TASSEL_USER_DATA',
  'TASSEL_UI_LANG',
  'TASSEL_TUTOR',
  'TASSEL_FAKE_SCRIPT',
  'TASSEL_FAKE_SPEED',
  'TASSEL_PAPER_SOURCE',
  'TASSEL_PAPER_DEBUG',
  'TASSEL_PAPER_PARAMS',
  'TASSEL_FAKE_CLIP',
  'TASSEL_HELPER_CLIP',
  'TASSEL_FAKE_CAMERA_ACCESS',
  'TASSEL_DESKVIEW_HELPER',
  'TASSEL_FAKE_DISPLAY',
]);

/** A minimal OS environment: open adds --env pairs to this inherited environment. */
export function cameraSubprocessEnv(env) {
  return Object.fromEntries(
    Object.entries(env).filter(
      ([key, value]) =>
        value !== undefined &&
        /^(PATH|HOME|USER|LOGNAME|SHELL|TMPDIR|TMP|TEMP|LANG|LC_[A-Z_]+|__CF_USER_TEXT_ENCODING)$/.test(
          key,
        ),
    ),
  );
}

/** Pure construction shared by the owner launcher and the opt-in spec. */
export function cameraLaunch(
  inherited,
  { electronApp, mainEntry, serverUrl, tag, log, userData, cdpPort },
) {
  const env =
    userData === undefined
      ? cameraEnv(inherited, { serverUrl })
      : [
          `TASSEL_SERVER_URL=${serverUrl}`,
          'TASSEL_TOKEN_STORE=file',
          `TASSEL_USER_DATA=${userData}`,
          'TASSEL_PAPER_SOURCE=auto',
        ];
  env.push(`TASSEL_HELPER_TAG=${tag}`);
  return {
    command: 'open',
    args: openArgs({
      electronApp,
      env,
      log,
      args: [
        mainEntry,
        ...(cdpPort === undefined ? [] : [`--remote-debugging-port=${cdpPort}`]),
        `--tassel-camera-run=${tag}`,
      ],
    }),
    options: { env: cameraSubprocessEnv(inherited), stdio: 'ignore' },
    message: '[camera] Launching Tassel through LaunchServices.',
  };
}
